package com.agentfit.coreapi.domain.analysis;

import com.agentfit.coreapi.domain.analysis.entity.*;
import com.agentfit.coreapi.domain.analysis.repository.*;
import com.agentfit.coreapi.domain.analysis.service.ProjectAnalysisService;
import com.agentfit.coreapi.domain.auth.entity.AuthenticatedPrincipal;
import com.agentfit.coreapi.domain.project.entity.*;
import com.agentfit.coreapi.domain.project.repository.*;
import com.agentfit.coreapi.domain.project.exception.AnalysisAlreadyProcessingException;
import java.time.*; import java.util.*;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;

class ProjectAnalysisServiceTest {
 @Test void acceptsProcessingAndRejectsSameProjectTwice(){ var project=new Project("p",1,"demo",1,"CREATED",0,0,Instant.now(),Instant.now(),"BACKEND",1L); var pr=new Projects(project); var ar=new Attempts(); var ad=new Admission(); var input=new Inputs(); var svc=new ProjectAnalysisService(pr,ar,ad,input,Clock.fixed(Instant.parse("2026-01-01T00:00:00Z"),ZoneOffset.UTC),600); var principal=new AuthenticatedPrincipal(1,"u",null); var first=svc.start(principal,"p",1); assertEquals("PROCESSING",first.state()); assertThrows(AnalysisAlreadyProcessingException.class,()->svc.start(principal,"p",2)); }
 @Test void rejectsMissingInputAndStaleVersion(){ var project=new Project("p",1,"demo",2,"CREATED",0,0,Instant.now(),Instant.now(),"BACKEND",null); var svc=new ProjectAnalysisService(new Projects(project),new Attempts(),new Admission(),new Inputs(false),Clock.systemUTC(),600); assertThrows(com.agentfit.coreapi.global.exception.VersionConflictException.class,()->svc.start(new AuthenticatedPrincipal(1,"u",null),"p",1)); assertThrows(IllegalArgumentException.class,()->svc.start(new AuthenticatedPrincipal(1,"u",null),"p",2)); }
 @Test void appliesServerLimit(){ var project=new Project("p",1,"demo",1,"CREATED",0,0,Instant.now(),Instant.now(),"BACKEND",1L); var attempts=new Attempts(); attempts.list.add(new AnalysisAttempt(1,"other","r",1,"1","PROCESSING",Instant.now().plusSeconds(1),Instant.now(),null,2L,1L,null)); attempts.list.add(new AnalysisAttempt(2,"other2","r2",1,"1","PROCESSING",Instant.now().plusSeconds(1),Instant.now(),null,3L,1L,null)); var svc=new ProjectAnalysisService(new Projects(project),attempts,new Admission((short)2),new Inputs(),Clock.systemUTC(),600); assertThrows(com.agentfit.coreapi.domain.project.exception.AnalysisCapacityExceededException.class,()->svc.start(new AuthenticatedPrincipal(1,"u",null),"p",1)); }
 @Test void appliesUserLimit(){ var project=new Project("p",1,"demo",1,"CREATED",0,0,Instant.now(),Instant.now(),"BACKEND",1L); var attempts=new Attempts(); attempts.list.add(new AnalysisAttempt(1,"other","r",1,"1","PROCESSING",Instant.now().plusSeconds(1),Instant.now(),null,1L,1L,null)); var svc=new ProjectAnalysisService(new Projects(project),attempts,new Admission(),new Inputs(),Clock.systemUTC(),600); var ex=assertThrows(com.agentfit.coreapi.domain.project.exception.AnalysisCapacityExceededException.class,()->svc.start(new AuthenticatedPrincipal(1,"u",null),"p",1)); assertEquals(com.agentfit.coreapi.global.exception.ErrorCode.ANALYSIS_USER_LIMIT_REACHED,ex.getErrorCode()); }
 static class Projects implements ProjectRepository { Project p; Projects(Project p){this.p=p;} public Project save(Project x){p=x;return x;} public List<Project> findByOwnerId(long o){return List.of(p);} public Optional<Project> findByIdAndOwnerId(String i,long o){return Optional.of(p);} public Optional<Project> findByIdForUpdate(String i){return Optional.of(p);} public void markAnalysisStarted(String i,long g,long v,Instant t){p=new Project(p.id(),p.ownerId(),p.name(),v,"PROCESSING",g,p.reviewGeneration(),p.createdAt(),t,p.developerRole(),p.currentInputRevision());} }
 static class Attempts implements AnalysisAttemptRepository { List<AnalysisAttempt> list=new ArrayList<>(); public AnalysisAttempt start(AnalysisAttempt a){var x=new AnalysisAttempt(1,a.projectId(),a.requestId(),a.generation(),a.contractVersion(),a.state(),a.deadlineAt(),a.startedAt(),a.completedAt(),a.ownerId(),a.inputRevision(),a.errorCode());list.add(x);return x;} public Optional<AnalysisAttempt> findProcessingByProjectId(String p){return list.stream().filter(a->a.projectId().equals(p)&&a.state().equals("PROCESSING")).findFirst();} public Optional<AnalysisAttempt> findProcessingByOwnerId(long o){return list.stream().filter(a->Objects.equals(a.ownerId(),o)&&a.state().equals("PROCESSING")).findFirst();} }
 static class Admission implements AnalysisAdmissionRepository { short count; Admission(){this((short)0);} Admission(short c){count=c;} public AnalysisAdmission lock(){return new AnalysisAdmission((short)1,count,Instant.now());} public void increment(){count++;} }
 static class Inputs implements PlanningInputRepository { boolean present=true; Inputs(){} Inputs(boolean p){present=p;} public Optional<PlanningInput> findCurrent(String p){return present?Optional.of(new PlanningInput(p,1,"TEXT",null,"text/plain",1L,1,null,new byte[]{1},"x",null,Instant.now())):Optional.empty();} }
}
